export function clubWeekFixture(role='head'){
 const dates=['2026-10-24','2026-10-31'];
 const roster=Array.from({length:24},(_,i)=>({id:'p'+(i+1),name:'Player '+String(i+1).padStart(2,'0'),grade:i<11?'1st grade':'2nd grade',active:true,user_id:i===0?'player':null,batting:'top',bowling:i===23?'spin':'pace',bowling_load:'frontline',keeper:i===10||i===21,availability:{revision:1,available_dates:dates,unavailable_dates:[]}}));
 const fixtures=[0,1].map(i=>{const details={grade:(i?'2nd':'1st')+' grade',format:'long_form',opposition:'Harbour CC',ground:'City Oval',meeting:'Meet 30 minutes before play',days:dates.map(date=>({date,start:'12:00'})),brackets:true};const slots=Array.from({length:11},(_,n)=>({d1:'p'+(i*11+n+1),d2:'p'+(i*11+n+1)}));return {id:'f'+(i+1),revision:1,details,slots,publication:1,published:{details:structuredClone(details),slots:structuredClone(slots),players:roster.slice(i*11,i*11+11)}};});
 const state={clubId:'club',clubName:'Test Cricket Club',userId:role==='player'?'player':role,today:'2026-10-19',date:dates[0],view:role==='player'?'published':'board',data:{access:{timezone:'Australia/Sydney'},selector:role==='head'||role==='selector',admin:role==='admin',captain:role==='captain',publication_head_id:'head',fixtures,roster,week:{can_manage:role==='head'||role==='admin',calendar_active:false,settings:{revision:0,reminders_enabled:false,deadline_weekday:4,deadline_time:'18:00',acknowledgement_enabled:true},plans:[],acknowledgements:fixtures.flatMap(f=>f.published.players.map(p=>({fixture_id:f.id,roster_id:p.id,publication:1,linked:!!p.user_id,seen_at:null})))}}};
 if(role==='player'){state.data.roster=roster.filter(p=>p.user_id==='player');state.data.week.acknowledgements=state.data.week.acknowledgements.filter(a=>a.roster_id==='p1');}
 return state;
}
export const clubWeekHost=()=>'<main><div id="seContent"><div class="se-toolbar"></div><section class="se-card" data-se-team="f1"><h2>1st grade</h2><p>v Harbour CC · Sat 24 Oct / Sat 31 Oct</p></section><section class="se-card" data-se-team="f2"><h2>2nd grade</h2><p>v Harbour CC · Sat 24 Oct / Sat 31 Oct</p></section></div></main>';
